-- GENERATED by tools/gen_state_mod.py from templates/state_names and data/states/us_colorado; edit those, not this file.
-- Data lint for the shipped lists (content/square_names_us_colorado/data/*.lua), same rules as tools/gen_state_mod.py --check:
-- non-empty strings <= 40 bytes, valid UTF-8 (plain ASCII with asciiFallback), no duplicates, town names unique
-- after normalization, climate tags exist, every climate pool >= minPool towns, every city key is a town, no street
-- repeated across a city's kinds, contested.lua well-formed. Floors: state.lua minTowns / minPool /
-- minStreetCities, else 400 / 150 / 15 (the generator's defaults).

local MOD = "square_names_us_colorado"
local P = MOD .. "::/" .. MOD .. "/"
local L = ug_require(P .. "sn_logic.lua")
local towns = ug_require(P .. "data/towns.lua")
local streets = ug_require(P .. "data/streets.lua")
local cities = ug_require(P .. "data/cities.lua")
local state = ug_require(P .. "data/state.lua")
local contested = ug_require(P .. "data/contested.lua")
local MIN_TOWNS = state.minTowns or 400
local MIN_POOL = state.minPool or 150
local MIN_STREET_CITIES = state.minStreetCities or 15

local function validUtf8(s)
	local i, n = 1, #s
	while i <= n do
		local c = s:byte(i)
		local len = c < 0x80 and 1 or (c >= 0xC2 and c <= 0xDF) and 2 or (c >= 0xE0 and c <= 0xEF) and 3
			or (c >= 0xF0 and c <= 0xF4) and 4 or nil
		if not len or i + len - 1 > n then return false end
		for k = i + 1, i + len - 1 do
			local b = s:byte(k)
			if b < 0x80 or b > 0xBF then return false end
		end
		i = i + len
	end
	return true
end

local function checkName(s, where)
	ok(type(s) == "string" and s ~= "", where .. ": empty or not a string")
	ok(#s <= 40, where .. ": longer than 40 bytes: " .. s)
	ok(validUtf8(s), where .. ": invalid UTF-8")
	ok(s == s:gsub("^%s+", ""):gsub("%s+$", ""), where .. ": leading/trailing space: '" .. s .. "'")
	if state.asciiFallback then ok(not s:find("[\128-\255]"), where .. ": not ASCII (asciiFallback): " .. s) end
end

local function checkList(list, where)
	ok(type(list) == "table" and #list > 0, where .. ": empty list")
	local seen = {}
	for i, s in ipairs(list) do
		checkName(s, where .. "[" .. i .. "]")
		local k = L.normalize(s)
		ok(not seen[k], where .. ": duplicate " .. s)
		seen[k] = true
	end
end

test("towns: names, tags, populations, unique", function()
	ok(#towns >= MIN_TOWNS, "at least " .. MIN_TOWNS .. " towns, got " .. #towns)
	local seen = {}
	for i, t in ipairs(towns) do
		checkName(t.n, "towns[" .. i .. "]")
		local k = L.normalize(t.n)
		ok(not seen[k], "duplicate town " .. t.n)
		seen[k] = true
		ok(type(t.t) == "table" and #t.t > 0, t.n .. ": no tags")
		ok(type(t.p) == "number" and t.p >= 0, t.n .. ": bad population")
		if i > 1 then ok(towns[i - 1].p >= t.p, "towns sorted by population: " .. t.n) end
	end
end)

test("climates: tags exist and every pool has >= minPool towns", function()
	local tagSet = {}
	for _, t in ipairs(towns) do for _, tag in ipairs(t.t) do tagSet[tag] = true end end
	ok(type(state.climates) == "table")
	for climate, weights in pairs(state.climates) do
		local positive = 0
		for tag, w in pairs(weights) do
			ok(tagSet[tag], climate .. ": unknown tag " .. tag)
			ok(type(w) == "number" and w >= 0, climate .. ": bad weight for " .. tag)
			if w > 0 then positive = positive + 1 end
		end
		ok(positive > 0, climate .. ": no positive weight")
		local n = L.poolSize(towns, weights)
		ok(n >= MIN_POOL, climate .. ": pool of " .. n .. " towns, want >= " .. MIN_POOL)
		local res = L.sampleTowns(towns, 60, weights)
		eq(#res, 60)
	end
	for _, set in ipairs(state.regionalSets or {}) do
		for _, tag in ipairs(set.tags) do ok(tagSet[tag], set.id .. ": unknown tag " .. tag) end
	end
end)

test("generic streets", function()
	checkList(streets, "streets")
	ok(#streets >= 100, "about 120 generic streets, got " .. #streets)
end)

test("cities: keys are towns, lists clean, no name twice within a city", function()
	local townSet = {}
	for _, t in ipairs(towns) do townSet[L.normalize(t.n)] = true end
	local kinds = { "streets", "neighborhoods", "rail", "airport", "harbor" }
	local withStreets = 0
	for key, city in pairs(cities) do
		local known = townSet[L.normalize(key)]
		for _, a in ipairs(city.aliases or {}) do known = known or townSet[L.normalize(a)] end
		ok(known, "city " .. key .. " is not a town in towns.lua")
		for k in pairs(city) do
			ok(k == "aliases" or L.KIND_LIST[k] ~= nil or k == "streets" or k == "neighborhoods",
				key .. ": unknown list " .. tostring(k))
		end
		local streetBase = {}
		for _, s in ipairs(city.streets or {}) do streetBase[L.baseName(s)] = true end
		for _, kind in ipairs(kinds) do
			if city[kind] then
				checkList(city[kind], key .. "." .. kind)
				if kind ~= "streets" then
					for _, s in ipairs(city[kind]) do
						ok(not streetBase[L.baseName(s)], key .. ": " .. s .. " is also one of its streets")
					end
				end
			end
		end
		if city.streets then withStreets = withStreets + 1 end
	end
	ok(withStreets >= MIN_STREET_CITIES, "at least " .. MIN_STREET_CITIES .. " cities with streets, got " .. withStreets)
end)

test("contested: normalized names -> series modIds", function()
	ok(type(contested) == "table")
	for name, winner in pairs(contested) do
		eq(L.normalize(name), name, "key is normalized")
		ok(type(winner) == "string" and winner:sub(1, #"square_names_us_") == "square_names_us_", name .. ": bad winner")
		ok(L.findCity(cities, name) ~= nil, name .. ": not one of this mod's cities")
	end
end)
